from pathlib import Path
import json,struct
r=Path(__file__).resolve().parents[1]
views=['human_plains','overhead','campaign','dwarf_foothills','northern_lake']
for v in views:
    p=r/'TerrainWork/Captures'/('L_grass_coast_v2_'+v+'.png')
