html+='''<script>const view=document.querySelector('#view'),slider=document.querySelector('#slider');function split(){document.querySelector('#after').style.clipPath=`inset(0 ${100-slider.value}% 0 0)`;document.querySelector('.split').style.left=slider.value+'%'}function update(){document.querySelector('#before').src='TerrainWork/Captures/L_mountain_campaign_'+view.value+'.png';document.querySelector('#after').src='TerrainWork/Captures/L_grass_coast_v2_'+view.value+'.png';document.querySelector('#full').href=document.querySelector('#after').src}view.onchange=update;slider.oninput=split;document.querySelector('#toggle').onclick=()=>{slider.value=slider.value<50?100:0;split()};update();split();</script></main></html>'''
